package com.bike.server.system;
import com.bike.server.common.ApiResponse; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/roles") public class RoleController { private final RoleService service; public RoleController(RoleService service){this.service=service;} @GetMapping public ApiResponse<List<RoleView>> list(@RequestParam(required=false)String keyword){return ApiResponse.success("查询成功",service.list(keyword));} @PostMapping public ApiResponse<RoleView> create(@Valid @RequestBody RoleCreateRequest request){return ApiResponse.success("创建成功",service.create(request));} @PutMapping("/{id}") public ApiResponse<RoleView> update(@PathVariable long id,@Valid @RequestBody RoleCreateRequest request){return ApiResponse.success("更新成功",service.update(id,request));} @PutMapping("/{id}/status") public ApiResponse<RoleView> status(@PathVariable long id,@RequestParam boolean enabled){return ApiResponse.success("更新成功",service.updateStatus(id,enabled));} @GetMapping("/{id}/permissions") public ApiResponse<List<PermissionView>> permissions(@PathVariable long id){return ApiResponse.success("查询成功",service.permissions(id));} @GetMapping("/permissions") public ApiResponse<List<PermissionView>> allPermissions(){return ApiResponse.success("查询成功",service.allPermissions());} @PutMapping("/{id}/permissions") public ApiResponse<List<PermissionView>> updatePermissions(@PathVariable long id,@Valid @RequestBody RolePermissionRequest request){return ApiResponse.success("权限更新成功",service.updatePermissions(id,request));} }
